content:
:root {
  --color-primary: #3b82f6;
  --color-primary-hover: #2563eb;
  --color-primary-light: #eff6ff;
  --color-text-main: #1e293b;
  --color-text-muted: #64748b;
  --color-text-light: #64748b;
  --color-bg-body: #f8fafc;
  --color-bg-card: #ffffff;
  --color-border: #e2e8f0;
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.05), 0 1px 2px rgba(0, 0, 0, 0.03);
  --radius-sm: 6px;
  --radius-md: 10px;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "BIZ UDPGothic", Meiryo, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--color-bg-body);
  color: var(--color-text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  padding: 24px 16px;
}

/* アプリケーション全体コンテナ */
.app-container {
  max-width: 960px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ヘッダー */
.app-header {
  text-align: left;
  padding: 8px 4px;
}

.app-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-text-main);
  letter-spacing: -0.02em;
  margin-bottom: 6px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.app-description {
  font-size: 0.925rem;
  color: var(--color-text-muted);
}

/* 検索・絞り込みコントロール */
.controls-card {
  background-color: var(--color-bg-card);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
  padding: 16px 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.search-box-wrapper {
  position: relative;
  display: flex;
  align-items: center;
  flex: 1;
  min-width: 240px;
}

.search-input {
  width: 100%;
  padding: 10px 38px 10px 14px;
  font-size: 0.95rem;
  font-family: inherit;
  color: var(--color-text-main);
  background-color: #f8fafc;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  outline: none;
  transition: all 0.2s ease;
}

.search-input:focus {
  background-color: #ffffff;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.search-input::placeholder {
  color: var(--color-text-light);
}

.search-clear-button {
  position: absolute;
  right: 10px;
  background: transparent;
  border: none;
  color: var(--color-text-light);
  font-size: 1.1rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  padding: 0;
  transition: all 0.15s ease;
}

.search-clear-button:hover {
  background-color: #e2e8f0;
  color: var(--color-text-main);
}

.result-count {
  font-size: 0.9rem;
  color: var(--color-text-muted);
  font-weight: 500;
  white-space: nowrap;
}

/* テーブルカードコンテナ */
.table-card {
  background-color: var(--color-bg-card);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}

.table-container {
  width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

/* 社員テーブル基本設定 */
.employee-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.925rem;
}

.employee-table th {
  background-color: #f8fafc;
  color: var(--color-text-muted);
  font-size: 0.825rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 12px 18px;
  border-bottom: 1px solid var(--color-border);
  user-select: none;
  white-space: nowrap;
}

.employee-table td {
  padding: 14px 18px;
  border-bottom: 1px solid var(--color-border);
  vertical-align: middle;
}

.employee-table tbody tr {
  transition: background-color 0.15s ease;
}

.employee-table tbody tr:hover {
  background-color: #f1f5f9;
}

.employee-table tbody tr:last-child td {
  border-bottom: none;
}

/* ソート可能見出しヘッダー */
.th-sortable {
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.th-sortable:hover {
  background-color: #edf2f7;
  color: var(--color-text-main);
}

.th-sortable:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: -2px;
}

.th-content {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.sort-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85rem;
  color: var(--color-text-light);
  transition: color 0.15s ease;
}

.sort-icon-active {
  color: var(--color-primary);
  font-weight: 700;
}

/* テーブル各列スタイル */
.td-id {
  color: var(--color-text-light);
  font-family: monospace;
  font-size: 0.85rem;
  font-weight: 600;
  width: 60px;
}

.td-name {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.td-name-main {
  font-weight: 600;
  color: var(--color-text-main);
}

.td-name-sub {
  font-size: 0.775rem;
  color: var(--color-text-light);
}

.td-dept {
  white-space: nowrap;
}

/* 部署タグバッジ */
.dept-tag {
  display: inline-block;
  padding: 3px 10px;
  border-radius: 9999px;
  font-size: 0.8rem;
  font-weight: 500;
  background-color: #f1f5f9;
  color: #475569;
  border: 1px solid #e2e8f0;
}

.dept-tag[data-dept="開発部"] {
  background-color: #eff6ff;
  color: #1d4ed8;
  border-color: #bfdbfe;
}

.dept-tag[data-dept="営業部"] {
  background-color: #ecfdf5;
  color: #047857;
  border-color: #a7f3d0;
}

.dept-tag[data-dept="総務部"] {
  background-color: #faf5ff;
  color: #7e22ce;
  border-color: #e9d5ff;
}

.dept-tag[data-dept="人事部"] {
  background-color: #fff1f2;
  color: #be123c;
  border-color: #fecdd3;
}

.dept-tag[data-dept="マーケティング部"] {
  background-color: #fffbeb;
  color: #b45309;
  border-color: #fde68a;
}

.dept-tag[data-dept="財務部"] {
  background-color: #f0fdf4;
  color: #15803d;
  border-color: #bbf7d0;
}

.dept-tag[data-dept="広報部"] {
  background-color: #fdf2f8;
  color: #be185d;
  border-color: #fbcfe8;
}

.td-age {
  white-space: nowrap;
}

.age-value {
  font-weight: 500;
  color: var(--color-text-main);
}

/* 検索結果が空の場合 */
.empty-message {
  padding: 48px 16px;
  text-align: center;
  color: var(--color-text-muted);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.reset-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 8px 16px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-primary);
  background-color: var(--color-primary-light);
  border: 1px solid #bfdbfe;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.15s ease;
}

.reset-button:hover {
  background-color: #dbeafe;
  border-color: var(--color-primary);
}

.reset-button:active {
  transform: translateY(1px);
}

/* レスポンシブ調整 */
@media (max-width: 640px) {
  body {
    padding: 16px 8px;
  }

  .app-header {
    padding: 4px 0;
  }

  .app-title {
    font-size: 1.4rem;
  }

  .controls-card {
    padding: 12px;
    flex-direction: column;
    align-items: stretch;
  }

  .search-box-wrapper {
    min-width: 100%;
  }

  .result-count {
    text-align: right;
  }

  .employee-table th,
  .employee-table td {
    padding: 10px 12px;
  }
}

export type Department =
  | '開発部'
  | '営業部'
  | '総務部'
  | '人事部'
  | 'マーケティング部'
  | '財務部'
  | '広報部';

export type SortKey = 'id' | 'name' | 'department' | 'age' | 'role';

export type SortOrder = 'asc' | 'desc';

export interface SortConfig {
  key: SortKey;
  order: SortOrder;
}

export interface Employee {
  id: number;
  name: string;
  kana: string;
  department: Department;
  age: number;
  role: string;
}

import { ChangeEvent, KeyboardEvent, useRef } from 'react';

interface SearchBarProps {
  searchTerm: string;
  onSearchChange: (value: string) => void;
  onClear: () => void;
  totalCount: number;
  filteredCount: number;
}

const SearchBar = ({
  searchTerm = '',
  onSearchChange,
  onClear,
  totalCount = 0,
  filteredCount = 0
}: SearchBarProps) => {
  const inputRef = useRef<HTMLInputElement>(null);

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    onSearchChange?.(e.target.value);
  };

  const handleClear = () => {
    onClear?.();
    inputRef.current?.focus();
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Escape') {
      onClear?.();
    }
  };

  return (
    <div className="controls-card">
      <div className="search-box-wrapper">
        <input
          ref={inputRef}
          type="text"
          className="search-input"
          placeholder="名前またはフリガナで検索..."
          value={searchTerm}
          onChange={handleChange}
          onKeyDown={handleKeyDown}
          aria-label="名前またはフリガナで検索"
        />
        {searchTerm.length > 0 && (
          <button
            type="button"
            className="search-clear-button"
            onClick={handleClear}
            title="検索条件をクリア"
            aria-label="検索条件をクリア"
          >
            ×
          </button>
        )}
      </div>
      <div className="result-count">
        該当人数: {filteredCount} / {totalCount} 名
      </div>
    </div>
  );
};

export default SearchBar;

import { KeyboardEvent } from 'react';
import { Employee, SortConfig, SortKey } from '../types';

interface EmployeeTableProps {
  employees: Employee[];
  sortConfig: SortConfig;
  onSort: (key: SortKey) => void;
  onResetFilters: () => void;
}

interface ColumnDefinition {
  key: SortKey;
  label: string;
}

const columns: ColumnDefinition[] = [
  { key: 'id', label: 'ID' },
  { key: 'name', label: '氏名' },
  { key: 'department', label: '部署' },
  { key: 'age', label: '年齢' }
];

const EmployeeTable = ({
  employees = [],
  sortConfig,
  onSort,
  onResetFilters
}: EmployeeTableProps) => {
  const handleSortClick = (key: SortKey) => {
    onSort?.(key);
  };

  const handleSortKeyDown = (e: KeyboardEvent<HTMLTableCellElement>, key: SortKey) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      handleSortClick(key);
    }
  };

  const handleResetClick = () => {
    onResetFilters?.();
  };

  const getSortAriaLabel = (column: ColumnDefinition) => {
    if (sortConfig.key !== column.key) {
      return `${column.label}: クリックして昇順でソート`;
    }
    return sortConfig.order === 'asc'
      ? `${column.label}: 現在昇順。クリックして降順でソート`
      : `${column.label}: 現在降順。クリックして昇順でソート`;
  };

  const renderSortIcon = (key: SortKey) => {
    const isActive = sortConfig.key === key;
    const iconClass = isActive ? 'sort-icon sort-icon-active' : 'sort-icon';

    if (!isActive) {
      return <span className={iconClass} aria-hidden="true">⇅</span>;
    }

    return (
      <span className={iconClass} aria-hidden="true">
        {sortConfig.order === 'asc' ? '▲' : '▼'}
      </span>
    );
  };

  if (employees.length === 0) {
    return (
      <div className="table-card">
        <div className="empty-message">
          <p>条件に一致する社員が見つかりませんでした。</p>
          <button
            type="button"
            className="reset-button"
            onClick={handleResetClick}
          >
            検索条件をリセット
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="table-card">
      <div className="table-container">
        <table className="employee-table">
          <thead>
            <tr>
              {columns.map((column) => (
                <th
                  key={column.key}
                  role="columnheader"
                  tabIndex={0}
                  className="th-sortable"
                  onClick={() => handleSortClick(column.key)}
                  onKeyDown={(e) => handleSortKeyDown(e, column.key)}
                  aria-label={getSortAriaLabel(column)}
                  aria-sort={
                    sortConfig.key === column.key
                      ? sortConfig.order === 'asc'
                        ? 'ascending'
                        : 'descending'
                      : 'none'
                  }
                >
                  <div className="th-content">
                    <span>{column.label}</span>
                    {renderSortIcon(column.key)}
                  </div>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {employees.map((employee) => (
              <tr key={employee.id}>
                <td className="td-id">#{employee.id}</td>
                <td>
                  <div className="td-name">
                    <span className="td-name-main">{employee.name}</span>
                    <span className="td-name-sub">
                      {employee.kana} • {employee.role}
                    </span>
                  </div>
                </td>
                <td className="td-dept">
                  <span className="dept-tag" data-dept={employee.department}>
                    {employee.department}
                  </span>
                </td>
                <td className="td-age">
                  <span className="age-value">{employee.age}</span> 歳
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default EmployeeTable;

import { useState, useMemo, useDeferredValue } from 'react';
import { initialEmployees } from './data';
import { Employee, SortConfig, SortKey } from './types';
import SearchBar from './components/SearchBar';
import EmployeeTable from './components/EmployeeTable';

/**
 * ひらがなをカタカナに変換する関数
 */
const toKatakana = (str: string): string => {
  return str.replace(/[\u3041-\u3096]/g, (match) =>
    String.fromCharCode(match.charCodeAt(0) + 0x60)
  );
};

/**
 * 検索用の文字列正規化（NFKC正規化、小文字化、スペース除去、カタカナ化）
 */
const normalizeSearchText = (text: string): string => {
  return toKatakana(text.normalize('NFKC').toLowerCase()).replace(/\s+/g, '');
};

const App = () => {
  const [employees] = useState<Employee[]>(initialEmployees);
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [sortConfig, setSortConfig] = useState<SortConfig>({
    key: 'id',
    order: 'asc'
  });

  const deferredSearchTerm = useDeferredValue(searchTerm);

  const handleSearchChange = (term: string) => {
    setSearchTerm(term);
  };

  const handleClearSearch = () => {
    setSearchTerm('');
  };

  const handleResetFilters = () => {
    setSearchTerm('');
    setSortConfig({ key: 'id', order: 'asc' });
  };

  const handleSort = (key: SortKey) => {
    setSortConfig((prev) => {
      if (prev.key === key) {
        return {
          key,
          order: prev.order === 'asc' ? 'desc' : 'asc'
        };
      }
      return {
        key,
        order: 'asc'
      };
    });
  };

  const filteredAndSortedEmployees = useMemo(() => {
    const normalizedQuery = normalizeSearchText(deferredSearchTerm);

    const filtered = employees.filter((employee) => {
      if (!normalizedQuery) {
        return true;
      }
      const normalizedName = normalizeSearchText(employee.name);
      const normalizedKana = normalizeSearchText(employee.kana);
      return (
        normalizedName.includes(normalizedQuery) ||
        normalizedKana.includes(normalizedQuery)
      );
    });

    return [...filtered].sort((a, b) => {
      let comparison = 0;

      switch (sortConfig.key) {
        case 'id':
          comparison = a.id - b.id;
          break;
        case 'age':
          comparison = a.age - b.age;
          break;
        case 'name':
          comparison = a.kana.localeCompare(b.kana, 'ja');
          break;
        case 'department':
          comparison = a.department.localeCompare(b.department, 'ja');
          break;
        default:
          comparison = 0;
      }

      return sortConfig.order === 'asc' ? comparison : -comparison;
    });
  }, [employees, deferredSearchTerm, sortConfig]);

  return (
    <div className="app-container">
      <header className="app-header">
        <h1 className="app-title">
          <span>👥</span> 社員名簿一覧
        </h1>
        <p className="app-description">
          社員情報の閲覧・名前によるリアルタイム絞り込みおよび各項目の昇順・降順ソートが可能です。
        </p>
      </header>

      <SearchBar
        searchTerm={searchTerm}
        onSearchChange={handleSearchChange}
        onClear={handleClearSearch}
        totalCount={employees.length}
        filteredCount={filteredAndSortedEmployees.length}
      />

      <EmployeeTable
        employees={filteredAndSortedEmployees}
        sortConfig={sortConfig}
        onSort={handleSort}
        onResetFilters={handleResetFilters}
      />
    </div>
  );
};

export default App;
